-- 2D-H: authorized mutations on two real self-service tenant bootstraps.
-- All creation and role demotion are inside the ROLLBACK transaction.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=public,extensions,pg_catalog;
SELECT plan(32);
CREATE TEMP TABLE _actors(label text,uid uuid,org uuid,branch uuid,register uuid,role uuid) ON COMMIT DROP;
INSERT INTO _actors(label,uid) SELECT label,gen_random_uuid() FROM (VALUES('A'),('B')) t(label);
GRANT SELECT,UPDATE ON _actors TO authenticated;
SET LOCAL session_replication_role=replica;
INSERT INTO auth.users(id,aud,role,email,email_confirmed_at)
SELECT uid,'authenticated','authenticated','2dh-admin-'||uid||'@example.invalid',now() FROM _actors;
SET LOCAL session_replication_role=origin;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub',(SELECT uid::text FROM _actors WHERE label='A'),true);
UPDATE _actors SET org=(public.create_my_organization_v1('2DH managed A','PE','PEN','America/Lima')->>'organization_id')::uuid WHERE label='A';
SELECT set_config('request.jwt.claim.sub',(SELECT uid::text FROM _actors WHERE label='B'),true);
UPDATE _actors SET org=(public.create_my_organization_v1('2DH managed B','PE','PEN','America/Lima')->>'organization_id')::uuid WHERE label='B';
SELECT set_config('request.jwt.claim.sub',(SELECT uid::text FROM _actors WHERE label='A'),true);
UPDATE _actors SET branch=(public.create_branch_v1('SECURE','Managed branch A','A street')->>'id')::uuid WHERE label='A';
SELECT set_config('request.jwt.claim.sub',(SELECT uid::text FROM _actors WHERE label='B'),true);
UPDATE _actors SET branch=(public.create_branch_v1('SECURE','Managed branch B','B street')->>'id')::uuid WHERE label='B';
SELECT set_config('request.jwt.claim.sub',(SELECT uid::text FROM _actors WHERE label='A'),true);
UPDATE _actors SET register=(public.create_cash_register_v1(branch,'SECONDARY','Managed register A')->>'id')::uuid WHERE label='A';
SELECT set_config('request.jwt.claim.sub',(SELECT uid::text FROM _actors WHERE label='B'),true);
UPDATE _actors SET register=(public.create_cash_register_v1(branch,'SECONDARY','Managed register B')->>'id')::uuid WHERE label='B';
SELECT set_config('request.jwt.claim.sub',(SELECT uid::text FROM _actors WHERE label='A'),true);
UPDATE _actors SET role=(public.create_role_v1('audit_role','Managed role A',ARRAY['products.update'])->>'id')::uuid WHERE label='A';
SELECT set_config('request.jwt.claim.sub',(SELECT uid::text FROM _actors WHERE label='B'),true);
UPDATE _actors SET role=(public.create_role_v1('audit_role','Managed role B',ARRAY['products.update'])->>'id')::uuid WHERE label='B';
RESET ROLE;
SELECT ok((SELECT count(*)=1 FROM public.branches b JOIN _actors a ON a.branch=b.id AND a.org=b.organization_id WHERE a.label='A' AND NOT b.is_main),'A owns branch');
SELECT ok((SELECT count(*)=1 FROM public.branches b JOIN _actors a ON a.branch=b.id AND a.org=b.organization_id WHERE a.label='B' AND NOT b.is_main),'B owns branch');
SELECT ok((SELECT count(*)=1 FROM public.cash_registers r JOIN _actors a ON a.register=r.id AND a.org=r.organization_id AND a.branch=r.branch_id WHERE a.label='A'),'A owns register');
SELECT ok((SELECT count(*)=1 FROM public.cash_registers r JOIN _actors a ON a.register=r.id AND a.org=r.organization_id AND a.branch=r.branch_id WHERE a.label='B'),'B owns register');
SELECT ok((SELECT count(*)=1 FROM public.roles r JOIN _actors a ON a.role=r.id AND a.org=r.organization_id WHERE a.label='A'),'A owns custom role');
SELECT ok((SELECT count(*)=1 FROM public.roles r JOIN _actors a ON a.role=r.id AND a.org=r.organization_id WHERE a.label='B'),'B owns custom role');
SELECT ok((SELECT count(*)=1 FROM public.role_permissions r JOIN _actors a ON a.role=r.role_id AND a.org=r.organization_id WHERE a.label='A' AND r.permission_code='products.update'),'A role permission is local');
SELECT ok((SELECT count(*)=1 FROM public.role_permissions r JOIN _actors a ON a.role=r.role_id AND a.org=r.organization_id WHERE a.label='B' AND r.permission_code='products.update'),'B role permission is local');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub',(SELECT uid::text FROM _actors WHERE label='A'),true);
SELECT throws_ok($q$SELECT public.create_cash_register_v1((SELECT branch FROM _actors WHERE label='B'),'FOREIGN','Foreign')$q$,'P0002',NULL,'Cannot create cash register in foreign branch');
SELECT is((SELECT count(*)::integer FROM public.branches WHERE organization_id=(SELECT org FROM _actors WHERE label='A')),2,'RLS restricts A to its two branches');
SELECT is((SELECT count(*)::integer FROM public.roles WHERE organization_id=(SELECT org FROM _actors WHERE label='A') AND code='audit_role'),1,'RLS restricts A to its own audit role');
SELECT throws_ok($q$SELECT public.complete_my_onboarding_step_v1(1,'unsupported_step')$q$,'22023',NULL,'Admin reaches onboarding argument validation');
RESET ROLE;
SET LOCAL session_replication_role=replica;
UPDATE public.app_users SET base_role='operador' WHERE user_id=(SELECT uid FROM _actors WHERE label='B');
UPDATE public.empleados SET rol='operador' WHERE auth_id=(SELECT uid FROM _actors WHERE label='B');
SET LOCAL session_replication_role=origin;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub',(SELECT uid::text FROM _actors WHERE label='B'),true);
SELECT is(public.get_user_role(),'operador','B now uses operator identity');
SELECT throws_ok($q$SELECT public.create_branch_v1('DENIED','Denied',NULL)$q$,'42501',NULL,'Operator cannot create branches');
SELECT throws_ok($q$SELECT public.create_cash_register_v1((SELECT branch FROM _actors WHERE label='B'),'DENIED','Denied')$q$,'42501',NULL,'Operator cannot create cash registers');
SELECT throws_ok($q$SELECT public.create_role_v1('denied','Denied',ARRAY[]::text[])$q$,'42501',NULL,'Operator cannot create custom roles');
SELECT throws_ok($q$SELECT public.complete_my_onboarding_step_v1(1,'business_profile')$q$,'42501',NULL,'Operator cannot complete onboarding');
RESET ROLE;
SELECT is((SELECT count(*)::integer FROM public.branches WHERE organization_id=(SELECT org FROM _actors WHERE label='B')),2,'Denied operator mutation keeps B branches intact');
SELECT is((SELECT count(*)::integer FROM public.cash_registers WHERE organization_id=(SELECT org FROM _actors WHERE label='B') AND code='SECONDARY'),1,'Denied operator mutation keeps B register intact');
-- Guided onboarding executed as authenticated owner A. Real bootstrap already
-- provisioned business profile, capabilities, main branch and default register.
CREATE TEMP TABLE _onboarding_step_result(step text,value jsonb) ON COMMIT DROP;
GRANT INSERT,SELECT ON _onboarding_step_result TO authenticated;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub',(SELECT uid::text FROM _actors WHERE label='A'),true);
SELECT throws_ok($q$SELECT public.complete_my_onboarding_step_v1(1,'operations')$q$,'22023',NULL,'Cannot skip required onboarding step');
INSERT INTO _onboarding_step_result SELECT 'business_profile',public.complete_my_onboarding_step_v1(1,'business_profile');
INSERT INTO _onboarding_step_result SELECT 'modules',public.complete_my_onboarding_step_v1(2,'modules');
INSERT INTO _onboarding_step_result SELECT 'operations',public.complete_my_onboarding_step_v1(3,'operations');
INSERT INTO _onboarding_step_result SELECT 'review',public.complete_my_onboarding_step_v1(4,'review');
SELECT throws_ok($q$SELECT public.complete_my_onboarding_step_v1(1,'review')$q$,'40001',NULL,'Stale onboarding revision rejected after completion');
INSERT INTO _onboarding_step_result SELECT 'repeat',public.complete_my_onboarding_step_v1(5,'review');
RESET ROLE;
SELECT is((SELECT value->>'next_step' FROM _onboarding_step_result WHERE step='business_profile'),'modules','First step advances to modules');
SELECT is((SELECT value->>'next_step' FROM _onboarding_step_result WHERE step='modules'),'operations','Second step advances to operations');
SELECT is((SELECT value->>'next_step' FROM _onboarding_step_result WHERE step='operations'),'review','Third step advances to review');
SELECT is((SELECT value->>'status' FROM _onboarding_step_result WHERE step='review'),'completed','Fourth step completes onboarding');
SELECT is((SELECT (value->>'revision')::int FROM _onboarding_step_result WHERE step='review'),5,'Sequential steps increment revision four times');
SELECT is((SELECT (value->>'revision')::int FROM _onboarding_step_result WHERE step='repeat'),5,'Repeat completion is idempotent');
SELECT is((SELECT jsonb_array_length(value->'completed_steps') FROM _onboarding_step_result WHERE step='review'),4,'All four onboarding milestones recorded');
SELECT is((SELECT status FROM public.organization_onboarding_progress WHERE organization_id=(SELECT org FROM _actors WHERE label='A')),'completed','Persisted A onboarding progression completes without impacting B');
-- A linked identity cannot bootstrap a second organization, even after
-- changing role to operator. The check is inside bootstrap_organization_v1.
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub',(SELECT uid::text FROM _actors WHERE label='A'),true);
SELECT throws_ok($q$SELECT public.create_my_organization_v1('Duplicate A','PE','PEN','America/Lima')$q$,'23505',NULL,'Admin A cannot create a second organization');
SELECT set_config('request.jwt.claim.sub',(SELECT uid::text FROM _actors WHERE label='B'),true);
SELECT throws_ok($q$SELECT public.create_my_organization_v1('Duplicate B','PE','PEN','America/Lima')$q$,'23505',NULL,'Operator B cannot create a second organization');
RESET ROLE;
SELECT is((SELECT count(*)::integer FROM public.organizations WHERE display_name IN ('2DH managed A','2DH managed B')),2,'Duplicate attempts do not create new tenants');
SELECT * FROM finish();
ROLLBACK;
